def getNewClassString(oldClassString, og):
    """ Return the new class string"""
    newClassString = oldClassString.replace("http://www.w3.org/2002/07/owl#", "http://www.w3.org/2002/07/owl#Class")
    if alreadyHasEntry(newClassString, og):
        newClassString = newClassString + "1"
    return newClassString

def getNewClass(oldClassString, og):
    """ Return the new class"""
    newClassString = getNewClassString(oldClassString, og)
    newClass = URIRef(newClassString)
    return newClass

